/// Word Hive's free-play modifier pool.
///
/// Exported so test/modifier_batch2_test.dart can check the pool the screen
/// actually uses instead of a copy that can drift out of step.
///
/// `momentum` earns its place here because Word Hive is one of the few games
/// with an unambiguous stream of correct and incorrect actions inside a single
/// level: every accepted word is a correct action and every rejected submission
/// is a mistake. Nothing in this pool contradicts it — `whisper`, `minimal` and
/// `spy` all make the *search* harder without changing what counts as a
/// correct action.
const List<String> kWordHiveModifierPool = [
  'whisper',
  'timer',
  'minimal',
  'spy',
  'momentum',
];

class SpellingBeeLevel {
  final String centerLetter;
  final List<String> outerLetters;
  final int targetCount;
  final Set<String> validWords;
  const SpellingBeeLevel({
    required this.centerLetter,
    required this.outerLetters,
    required this.targetCount,
    required this.validWords,
  });

  List<String> get allLetters => [centerLetter, ...outerLetters];
}

