class WordHiveScreen extends StatefulWidget {
  final int? dailyLevelIndex;
  const WordHiveScreen({super.key, this.dailyLevelIndex});
  @override
  State<WordHiveScreen> createState() => _WordHiveScreenState();
}

class _WordHiveScreenState extends State<WordHiveScreen> {
  String? _forcedModifier;
  int _levelIndex = 0;
  late SpellingBeeLevel _level;
  final List<String> _currentGuess = [];
  final List<int> _selectedIndices = [];
  final Set<String> _foundWords = {};
  String _message ='';
  bool _won = false;
  bool _isTutorialMode = false;
  bool _tutorialCompleted = false;
  bool _playDailyMode = false;
  String _dailyModifierType = '';
  String _dailyModifierName = '';
  String _dailyModifierDesc = '';

  final GlobalKey _honeycombKey = GlobalKey();
  final List<Offset> _linePoints = [];
  final ValueNotifier<Offset?> _currentDragNotifier = ValueNotifier<Offset?>(null);

  int _hintCount = 0;
  bool _shuffleActive = false;
  Set<String> _activeModifiers = {};

  // COGNIQ-FIX:mod-active-helper
  bool _isModActive(String name) {
    if (_forcedModifier == name) return true;
    if (_playDailyMode) return _dailyModifierType == name;
    // COGNIQ-FIX:mod-active-helper
    // Was 'wordhive', which is not a key in RotationEngine's start-level map,
    // so it silently fell back to the default of 15 while `_modsOn` and
    // `getActiveModifiers` both use 'spellingbee' (8). On levels 12-14 the
    // engine filled `_activeModifiers` and the banner announced a modifier,
    // yet every gameplay getter below returned false.
    return _levelIndex >= RotationEngine.modifierStartLevel('spellingbee') &&
        _activeModifiers.contains(name);
  }

  // COGNIQ-FIX:mod-getters
  bool get _isWhisper => _foundWords.length < 5 && _isModActive('whisper');
  bool get _isSpy => _isModActive('spy');
  bool get _isEndgame => _isModActive('timer');
  bool get _isMinimal => _isModActive('minimal');
  bool get _hasWhisperAndTimer => _isModActive('whisper') && _isModActive('timer');

  /// `momentum`: the combo chain for the level currently on screen.
  late final MomentumController _momentum =
      MomentumController(onChanged: () {
    if (mounted) setState(() {});
  });
  List<String> _spyOriginalWords = [];
  List<String> _spyScrambledWords = [];
  Timer? _gameTimer;
  bool _gameOver = false;
  int _timeLeft = -1;
  // Timer value at the moment the hard timer started; 0 when no timer ran.
  // Only used for the Speed Demon achievement check on clear.
  int _initialTime = 0;
  bool _timeBonusEarned = false;

  int get _minWordLength {
    if (_isTutorialMode) return 4;
    if (_playDailyMode) return 4;
    if (_levelIndex < 35) return 4;
    if (_levelIndex < 50) return 5;
    
    int desired = 5;
    if (_levelIndex >= 90) {
      desired = 5 + ((_levelIndex - 90) % 2);
    }
    
    if (_hasWhisperAndTimer) {
      desired--;
    }
    
    int validCount = _level.validWords.where((w) => w.length >= desired && w.contains(_level.centerLetter)).length;
    while (desired > 4 && validCount < 4) {
      desired--;
      validCount = _level.validWords.where((w) => w.length >= desired && w.contains(_level.centerLetter)).length;
    }
    return desired;
  }

  int get _targetCount {
    final int validCount = _level.validWords.where((w) => w.length >= _minWordLength && w.contains(_level.centerLetter)).length;
    int maxCap = 12;
    if (_hasWhisperAndTimer) {
      maxCap = 8;
    }
    final int capMax = min(maxCap, validCount);
    final int capMin = min(4, validCount);

    if (_playDailyMode && _dailyModifierType == 'whisper') {
      return 10.clamp(capMin, capMax);
    }
    if (_isEndgame) {
      final computedTarget = _level.targetCount + 4;
      return computedTarget.clamp(capMin, capMax);
    }
    // Climbs one extra word every five levels, so the ceiling of 12 arrives
    // around level 40 rather than level 20. The old rate hit the cap less than
    // a third of the way in and then never let up, which made every later level
    // the same maximum-length grind.
    final computedTarget = 5 + (_levelIndex ~/ 5);
    return computedTarget.clamp(capMin, capMax);
  }

  @override
  void dispose() {
    _gameTimer?.cancel();
    _momentum.dispose();
    _currentDragNotifier.dispose();
    super.dispose();
  }

  // COGNIQ-FIX:mod-desc-copy
  String _getModifierDescription(String mod) {
    switch (mod) {
      case 'whisper':
        return 'Center letter is hidden under a question mark.';
      case 'timer':
        return 'Find all target words before time expires.';
      case 'minimal':
        return 'Target word count is hidden.';
      case 'spy':
        return 'Target words are encrypted as anagrams.';
      case 'momentum':
        return 'Chain correct words quickly to multiply bonus points.';
      default:
        return '';
    }
  }

  String get _modifierBannerText {
    if (_isTutorialMode) return '';
    if (_playDailyMode) {
      if (_dailyModifierDesc.isNotEmpty) return _dailyModifierDesc;
      if (_dailyModifierName.isNotEmpty) return _dailyModifierName;
      return '';
    }
    return _activeModifiers
        .map(_getModifierDescription)
        .where((d) => d.isNotEmpty)
        .join(' · ');
  }

  /// Modifiers now begin at a per-game level chosen in RotationEngine
  /// rather than a flat level 30 for every game.
  bool get _modsOn => !_playDailyMode && RotationEngine.hasModifiers('spellingbee', _levelIndex);

  @override
  void initState() {
    super.initState();
    // Default synchronous initialization to avoid LateInitializationError
    _level = _kLevels[0];
    _initLevel();
  }

  Future<void> _initLevel() async {
    _hintCount = await HintManager.getHints('spellingbee');
    final prefs = await SharedPreferences.getInstance();
    _playDailyMode = prefs.getBool(PrefsKeys.playDailyMode) ?? false;
    if (_playDailyMode) {
      _dailyModifierType = prefs.getString(PrefsKeys.dailyModifierType) ?? '';
      _dailyModifierName = prefs.getString(PrefsKeys.dailyModifierName) ?? '';
      _dailyModifierDesc = prefs.getString(PrefsKeys.dailyModifierDesc) ?? '';
    } else {
      _dailyModifierType = '';
      _dailyModifierName = '';
      _dailyModifierDesc = '';
    }

    final savedLevel = prefs.getInt(PrefsKeys.gameLevel('spellingbee')) ?? 0;
    final active = await ShuffleManager.isActive();

    _isTutorialMode = false;
    _levelIndex = savedLevel;
 
    if (mounted) {
      setState(() {
        _shuffleActive = active;
        _loadLevel();
      });
      _checkSavedState();
    }
  }



  Future<void> _checkSavedState() async {
    if (_playDailyMode || _isTutorialMode) return;
    final prefs = await SharedPreferences.getInstance();
    Future.delayed(Duration.zero, () async {
        if (!mounted) return;
        final savedStateStr = prefs.getString(PrefsKeys.normalGameState('spellingbee'));
        if (savedStateStr != null) {
          try {
            final data = jsonDecode(savedStateStr);
            if (data['levelIndex'] == _levelIndex) {
              final continueGame = await showDialog<bool>(
                context: context,
                barrierDismissible: false,
                builder: (ctx) => AlertDialog(
                  backgroundColor: context.bgCard,
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(16),
                    side: BorderSide(color: context.textMuted.withAlpha(40)),
                  ),
                  title: Text(
                    'Continue Game?',
                    style: GoogleFonts.outfit(fontWeight: FontWeight.bold, color: context.textPrimary),
                  ),
                  content: Text(
                    'We found a saved state for this level. Would you like to continue playing or start a new game?',
                    style: GoogleFonts.outfit(color: context.textSecondary),
                  ),
                  actions: [
                    TextButton(
                      onPressed: () {
                        Navigator.pop(ctx, false); // New Game
                      },
                      child: Text(
                        'New Game',
                        style: GoogleFonts.outfit(color: Colors.redAccent, fontWeight: FontWeight.bold),
                      ),
                    ),
                    TextButton(
                      onPressed: () {
                        Navigator.pop(ctx, true); // Continue
                      },
                      child: Text(
                        'Continue',
                        style: GoogleFonts.outfit(color: AppTheme.dustyMauve, fontWeight: FontWeight.bold),
                      ),
                    ),
                  ],
                ),
              ) ?? false;

              if (continueGame) {
                final List<dynamic> wordsData = data['foundWords'];
                final Set<String> loadedFoundWords = Set<String>.from(wordsData.map((e) => e as String));
                setState(() {
                  _foundWords.clear();
                  _foundWords.addAll(loadedFoundWords);
                });
              } else {
                await _clearNormalState();
              }
            } else {
              await _clearNormalState();
            }
          } catch (_) {
            await _clearNormalState();
          }
        }
      });
  }

  Future<void> _saveNormalState() async {
    if (_playDailyMode || _won) return;
    final prefs = await SharedPreferences.getInstance();
    final state = {
      'levelIndex': _levelIndex,
      'foundWords': _foundWords.toList(),
    };
    await prefs.setString(PrefsKeys.normalGameState('spellingbee'), jsonEncode(state));
  }

  Future<void> _clearNormalState() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.remove(PrefsKeys.normalGameState('spellingbee'));
  }

  Future<void> _savePersistedLevel(int lvl) async {
    _gameTimer?.cancel();
    if (_timeLeft > 0 && _timeBonusEarned) {
      await PointManager.addPoints(5);
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Speed Bonus! Earned +5 Points!', style: GoogleFonts.outfit(fontWeight: FontWeight.bold, color: Colors.black)),
            backgroundColor: Colors.amber,
            duration: const Duration(seconds: 2),
          ),
        );
      }
    }
    if (_playDailyMode) {
      return;
    }
    final prefs = await SharedPreferences.getInstance();
    await prefs.setInt(PrefsKeys.gameLevel('spellingbee'), lvl);
    final earned = await HintManager.onLevelCleared(
      'spellingbee',
      // Speed Demon: cleared a hard-timer level with more than half the
      // clock still left. _initialTime is 0 unless the timer modifier ran.
      isSpeedDemon: _initialTime > 0 && _timeLeft * 2 > _initialTime,
    );
    // `momentum`: the ONLY extra award, and it is the difference above the base
    // that HintManager.onLevelCleared just paid -- not a second full award. See
    // the economy note at the top of widgets/momentum_meter.dart. A x1 average
    // pays nothing, so a level that never chained is worth exactly what it was
    // worth before this modifier existed.
    if (_isModActive('momentum')) {
      final bonus = _momentum.bonusPoints;
      if (bonus > 0) {
        await PointManager.addPoints(bonus);
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                'Combo Streak! +$bonus Points '
                '(x${_momentum.averageMultiplier.toStringAsFixed(1)} average)',
                style: GoogleFonts.outfit(
                    fontWeight: FontWeight.bold, color: Colors.black),
              ),
              backgroundColor: AppTheme.warmAmber,
              duration: const Duration(seconds: 2),
            ),
          );
        }
      }
    }
    final newCount = await HintManager.getHints('spellingbee');
    setState(() {
      _hintCount = newCount;
    });
    await _clearNormalState();
  }

  Future<void> _useHint() async {
    if (_won || _hintCount <= 0) return;
    String? targetWord;
    final minLength = _minWordLength;
    if (_isSpy) {
      for (final word in _spyOriginalWords) {
        if (!_foundWords.contains(word)) {
          targetWord = word;
          break;
        }
      }
    } else {
      for (final word in _level.validWords) {
        if (word.length >= minLength && word.contains(_level.centerLetter) && !_foundWords.contains(word)) {
          targetWord = word;
          break;
        }
      }
    }
    if (targetWord == null) return;

    await HintManager.useHint('spellingbee');
    final newCount = await HintManager.getHints('spellingbee');

    setState(() {
      _hintCount = newCount;
      // COGNIQ-FIX:mod-getters
      final bool isMinimal = _isMinimal;
      final clue = (_isWhisper || isMinimal) ? '?' : targetWord!.substring(0, 1).toUpperCase();
      _message = isMinimal
          ? 'Hint: Try a word with ${targetWord!.length} letters'
          : 'Hint: Try a word starting with "$clue" (${targetWord!.length} letters)';
      AudioManager.playClick();
    });
  }

  void _loadLevel() {
    HintManager.startLevel('spellingbee');
    _level = _kLevels[_levelIndex % _kLevels.length];
    _currentGuess.clear();
    _selectedIndices.clear();
    _foundWords.clear();
    _linePoints.clear();
    _currentDragNotifier.value = null;
    _message ='';
    _won = false;
    _gameOver = false;
    // A new level starts a new chain. Without this the previous level's
    // multiplier and its average would both carry over and be paid twice.
    _momentum.reset();

    if (_modsOn) {
      _activeModifiers = RotationEngine.getActiveModifiers(
        gameId: 'spellingbee',
        levelIndex: _levelIndex,
        pool: kWordHiveModifierPool,
        minActive: 1,
        maxActive: 2,
        smallGrid: false,
      );
      if (_forcedModifier != null) {
        _activeModifiers = {_forcedModifier!};
      }
      // COGNIQ-FIX:mod-deadeffect
      // `whisper` + `timer` used to be broken up here by dropping 'timer',
      // which made `_hasWhisperAndTimer` -- and the two compensations built
      // for it, the shorter minimum word length and the target cap of 8 --
      // permanently unreachable. The combination is allowed to stand now, so
      // those compensations are the thing that keeps it fair rather than dead
      // code. `_isWhisper` also stops hiding the centre letter after five
      // finds, so the pair is hard rather than unfair.
    } else {
      _activeModifiers = {};
      if (_playDailyMode && _dailyModifierType.isNotEmpty) {
        _activeModifiers.add(_dailyModifierType);
      }
    }

    _gameTimer?.cancel();
    _timeLeft = -1;
    _timeBonusEarned = false;

    if (_isSpy) {
      final rand = Random(_levelIndex + 2026);
      final validList = _level.validWords
          .where((w) => w.length >= _minWordLength && w.contains(_level.centerLetter))
          .toList();
      validList.shuffle(rand);
      final count = _targetCount;
      _spyOriginalWords = validList.take(count).toList();
      _spyScrambledWords = _spyOriginalWords.map((word) {
        final chars = word.split('');
        int guard = 0;
        while (guard < 10) {
          chars.shuffle(rand);
          if (chars.join() != word) break;
          guard++;
        }
        return chars.join().toUpperCase();
      }).toList();
    } else {
      _spyOriginalWords = [];
      _spyScrambledWords = [];
    }

    // COGNIQ-FIX:mod-getters
    if (_isEndgame) {
      _timeLeft = 45 + (_targetCount * 15);
      _initialTime = _timeLeft;
      _timeBonusEarned = true;
      _gameTimer = Timer.periodic(const Duration(seconds: 1), (timer) {
        if (mounted) {
          setState(() {
            if (_timeLeft > 0) {
              _timeLeft--;
            } else {
              _timeLeft = 0;
              _timeBonusEarned = false;
              _gameTimer?.cancel();
              AudioManager.playFail();
              _gameOver = true;
            }
          });
        }
      });
    }
  }

