  }

  void _reset() => setState(() => _loadLevel());

  String _maskWord(String w) {
    if (_isWhisper) {
      return w.replaceAll(_level.centerLetter, '?');
    }
    return w;
  }

  void _addLetterToGuess(int index, String letter, Offset center) {
    if (_won) return;
    if (_selectedIndices.isEmpty || _selectedIndices.last != index) {
      setState(() {
        _currentGuess.add(letter);
        _selectedIndices.add(index);
        _linePoints.add(center);
        _currentDragNotifier.value = center;
        _message = '';
        if (_selectedIndices.length == 1) {
          AudioManager.playClick();
        }
      });
    }
  }

  void _handlePan(Offset globalPos) {
    final box = _honeycombKey.currentContext?.findRenderObject() as RenderBox?;
    if (box == null) return;
    final local = box.globalToLocal(globalPos);
    final size = box.size.width;
    final ctr = Offset(size / 2, size / 2);
    final scaleVal = size / 200.0;

    // Check center letter (index 0)
    final distCenter = (local - ctr).distance;
    if (distCenter < 20.0 * scaleVal) {
      _addLetterToGuess(0, _level.centerLetter, ctr);
      return;
    }

    // Check outer letters (indices 1 to 6)
    for (int i = 0; i < 6; i++) {
      final angle = i * pi / 3 - pi / 6;
      final radius = 75.0 * scaleVal;
      final x = radius * cos(angle);
      final y = radius * sin(angle);
      final outerCenter = ctr + Offset(x, y);
      final distOuter = (local - outerCenter).distance;
      if (distOuter < 20.0 * scaleVal) {
        _addLetterToGuess(i + 1, _level.outerLetters[i], outerCenter);
        return;
      }
    }

    _currentDragNotifier.value = local;
  }

  void _handlePanEnd() {
    if (_currentGuess.isNotEmpty) {
      _submitWord();
    }
    _currentDragNotifier.value = null;
    setState(() {
      _selectedIndices.clear();
      _linePoints.clear();
    });
  }

  void _backspace() {
    if (_won || _currentGuess.isEmpty) return;
    setState(() {
      _currentGuess.removeLast();
      if (_selectedIndices.isNotEmpty) {
        _selectedIndices.removeLast();
      }
      if (_linePoints.isNotEmpty) {
        _linePoints.removeLast();
      }
      AudioManager.playClick();
    });
  }


  /// `momentum` scoring hooks. Gated on the modifier so no chain is tracked --
  /// and no decay timer is ever created -- on a level that is not running it.
  void _momentumCorrect() {
    if (_isModActive('momentum')) _momentum.correct();
  }

  void _momentumMistake() {
    if (_isModActive('momentum')) _momentum.mistake();
  }

  void _submitWord() {
    if (_won || _currentGuess.isEmpty) return;
    final word = _currentGuess.join();
    final minLength = _minWordLength;
    if (word.length < minLength) {
      setState(() {
        _message = 'Word must be at least $minLength letters';
        _currentGuess.clear();
        _selectedIndices.clear();
        AudioManager.playFail();
      });
      _momentumMistake();
      return;
    }
    if (!word.contains(_level.centerLetter)) {
      setState(() {
        final displayCenter = _isWhisper ? '?' : _level.centerLetter;
        _message ='Must contain center letter "$displayCenter"';
        _currentGuess.clear();
        _selectedIndices.clear();
        AudioManager.playFail();
      });
      _momentumMistake();
      return;
    }
    if (_foundWords.contains(word)) {
      setState(() {
        _message ='Already found "${_maskWord(word)}"';
        _currentGuess.clear();
        _selectedIndices.clear();
        AudioManager.playFail();
      });
      _momentumMistake();
      return;
    }
    if (_level.validWords.contains(word)) {
      if (_isSpy && !_spyOriginalWords.contains(word)) {
        setState(() {
          _message = 'Valid word, but not one of the encrypted words!';
          _currentGuess.clear();
          _selectedIndices.clear();
          AudioManager.playFail();
        });
        _momentumMistake();
        return;
      }
      // Before the win check below, so the word that clears the level is part
      // of the average the bonus is paid on.
      _momentumCorrect();
      setState(() {
        _foundWords.add(word);
        _message ='Nice! +1 word';
        _currentGuess.clear();
        _selectedIndices.clear();
        if (_foundWords.length >= _targetCount) {
          if (_isTutorialMode) {
            _tutorialCompleted = true;
            _message = 'Tutorial complete!';
            AudioManager.playSuccess();
          } else {
            _won = true;
            _message = 'Word Hive cleared!';
            AudioManager.playSuccess();
            _savePersistedLevel(_levelIndex + 1);
          }
        } else {
          AudioManager.playClick();
        }
      });
      _saveNormalState();
    } else {
      setState(() {
        _message ='"${_maskWord(word)}" is not in our word list!';
        _currentGuess.clear();
        _selectedIndices.clear();
        AudioManager.playFail();
      });
      _momentumMistake();
    }
  }

  void _nextLevel() async {
    if (!_won) return;
    if (_playDailyMode) {
      Navigator.pop(context, true);
      return;
    }
    if (await ShuffleManager.tryShuffleNavigate(context, 'spellingbee')) return;
 
    setState(() {
      _levelIndex = _levelIndex + 1;
      _loadLevel();
    });
  }

  @override
