          // they only fitted on unusually wide screens.
          PopupMenuButton<String>(
            icon: Icon(Icons.more_vert, color: context.textMuted),
            onSelected: (val) {
              if (val == 'help') {
                RulesHelper.showRulesBottomSheet(context, 'spellingbee', 'Word Hive');
              } else if (val == 'reset') {
                _reset();
              }
