                          // Banner and momentum meter moved inside the
                          // scrollable region above: they are what grows as
                          // more modifiers go live, so they are what has to
                          // yield on a short screen rather than pushing the
                          // hive off the bottom of the page.
                          Column(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              const SizedBox(height: 16),
                              if (_modifierBannerText.isNotEmpty) ...[
                                Padding(
                                  padding: const EdgeInsets.only(bottom: 8.0),
                                  child: Text(
                                    _modifierBannerText,
                                    textAlign: TextAlign.center,
                                    style: GoogleFonts.outfit(
                                      fontSize: 13,
                                      fontWeight: FontWeight.w600,
                                      color: accentColor.withOpacity(0.9),
                                    ),
                                  ),
                                ),
                              ],
                              // `momentum` has to be *visible* while it is
                              // running, not just paid out at the end
                              // (remember.md E2 section 8). A Wrap on its own
                              // row, so the chip can never overflow a sibling.
                              if (_isModActive('momentum')) ...[
                                Padding(
                                  padding: const EdgeInsets.only(bottom: 8.0),
                                  child: Wrap(
                                    alignment: WrapAlignment.center,
                                    children: [MomentumMeter(controller: _momentum)],
                                  ),
                                ),
                              ],
                            ],
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
              ),
              // Message / Display Current Guess
              Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  if (_message.isNotEmpty)
                    Padding(
                      padding: const EdgeInsets.only(bottom: 8.0),
                      child: Text(
                        _message,
                        style: GoogleFonts.outfit(
                          color: _won ? accentColor : Colors.redAccent,
                          fontWeight: FontWeight.bold,
                          fontSize: context.scale(13),
                        ),
                      ),
                    ),
                  // Current selection display - tap to submit
                  GestureDetector(
                    onTap: () {
                      if (_currentGuess.isNotEmpty) _submitWord();
                    },
                    child: Container(
                      height: 45,
                      alignment: Alignment.center,
                      decoration: BoxDecoration(
                        border: Border(bottom: BorderSide(color: context.textMuted.withAlpha(30), width: 1)),
                      ),
                      child: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Text(
                            _isWhisper
                                ? _currentGuess.map((char) => char == _level.centerLetter ? '?' : char).join()
                                : _currentGuess.join(),
                            style: GoogleFonts.outfit(
                              fontSize: context.scale(24),
                              fontWeight: FontWeight.w800,
                              color: context.textPrimary,
                              letterSpacing: 4,
                            ),
                          ),
                          if (_currentGuess.isNotEmpty) ...[
                            const SizedBox(width: 8),
                            Icon(Icons.check_circle_outline, size: context.scale(18), color: accentColor.withOpacity(0.7)),
                          ],
                        ],
                      ),
                    ),
                  ),
                ],
              ),
              // 16 rather than 24: on a 320x568 phone with a modifier caption on
              // screen this Column was 59px over its page, and every point of
              // padding around the hive is part of that budget.
              const SizedBox(height: 16),
              // Circular Honeycomb Layout.
              //
              // It used to be a hard 200x200 in a Column with one Expanded
              // above it, so on a 320x568 phone the fixed children alone came
              // to 59px more than the page — and layout_overflow_test.dart
              // never saw it, because it only ever booted level 0 where no
              // modifier caption is on screen to push the total over.
              //
              // Capping it against the viewport and scaling down inside that cap
              // makes the overflow structurally impossible: the hive keeps its
              // full size on any screen with room for it (every phone from
              // ~660px of usable height up) and shrinks uniformly where there is
              // not, instead of pushing the page past its bounds.
              //
              // A flex slot was tried first and rejected: it takes its share of
              // the height whether the hive needs it or not, which starved the
              // found-words list on a tall phone to pad whitespace around a
              // 200px hive.
              //
              // Scaling is safe because `_handlePan` already normalises with
              // `scaleVal = box.size.width / 200` and reads its coordinates
              // through `globalToLocal`, which inverts the FittedBox transform —
              // so the drag hit-testing, the drawn connector line and the letter
              // positions all stay in the same 200-unit space at any scale.
              ConstrainedBox(
                constraints: BoxConstraints(
                  maxHeight: min(
                    context.scale(200),
                    (MediaQuery.sizeOf(context).height - 120) * 0.28,
                  ),
                ),
                child: FittedBox(
                  fit: BoxFit.scaleDown,
                  child: Center(
                child: RepaintBoundary(
                  child: GestureDetector(
                      onPanStart: (d) => _handlePan(d.globalPosition),
                      onPanUpdate: (d) => _handlePan(d.globalPosition),
                      onPanEnd: (d) => _handlePanEnd(),
                      child: SizedBox(
                        key: _honeycombKey,
                        width: context.scale(200),
                        height: context.scale(200),
                        child: Stack(
                          alignment: Alignment.center,
                          children: [
                            // Line paint behind letters
                            Positioned.fill(
                              child: CustomPaint(
                                painter: _LineConnectorPainter(
                                  points: _linePoints,
                                  currentDragNotifier: _currentDragNotifier,
                                  color: accentColor,
                                ),
                              ),
                            ),
                          // Center letter button
                          GestureDetector(
                            onTap: () {
                              if (_won) return;
                              setState(() {
                                _currentGuess.add(_level.centerLetter);
                                _selectedIndices.add(0);
                                _linePoints.add(Offset(context.scale(100), context.scale(100)));
                                _message = '';
                              });
                            },
                            child: Container(
                              width: context.scale(56),
                              height: context.scale(56),
                              decoration: BoxDecoration(
                                color: accentColor,
                                shape: BoxShape.circle,
                                border: Border.all(
                                  color: _selectedIndices.contains(0) ? Colors.white : Colors.white.withAlpha(120),
                                  width: _selectedIndices.contains(0) ? 3.5 : 2,
                                ),
                                boxShadow: _selectedIndices.contains(0)
                                    ? [
                                        BoxShadow(
                                          color: accentColor.withOpacity(0.5),
                                          blurRadius: 8,
                                          spreadRadius: 2,
                                        )
                                      ]
                                    : null,
                              ),
                              child: Center(
                                child: Text(
                                  _isWhisper ? '?' : _level.centerLetter,
                                  style: GoogleFonts.outfit(
                                    fontSize: context.scale(22),
                                    fontWeight: FontWeight.w900,
                                    color: Colors.white,
                                  ),
                                ),
                              ),
                            ),
                          ),
                          // Outer letter buttons (6 of them)
                          ...List.generate(6, (index) {
                            final angle = index * pi / 3 - pi / 6;
                            final radius = context.scale(75.0);
                            final x = radius * cos(angle);
                            final y = radius * sin(angle);
                            final letter = _level.outerLetters[index];

                            return Positioned(
                              left: context.scale(100) + x - context.scale(24),
                              top: context.scale(100) + y - context.scale(24),
                              child: GestureDetector(
                                behavior: HitTestBehavior.opaque,
                                onTap: () {
                                  if (_won) return;
                                  final selectIdx = index + 1;
                                  setState(() {
                                    _currentGuess.add(letter);
                                    _selectedIndices.add(selectIdx);
                                    final angle = index * pi / 3 - pi / 6;
                                    final radius = context.scale(65.0);
                                    final x = radius * cos(angle);
                                    final y = radius * sin(angle);
                                    _linePoints.add(Offset(context.scale(100) + x, context.scale(100) + y));
                                    _message = '';
                                  });
                                },
                                child: Container(
                                  width: context.scale(48),
                                  height: context.scale(48),
                                  decoration: BoxDecoration(
                                    color: _selectedIndices.contains(index + 1)
                                        ? accentColor.withOpacity(0.15)
                                        : context.bgCard,
                                    shape: BoxShape.circle,
                                    border: Border.all(
                                      color: _selectedIndices.contains(index + 1)
                                          ? accentColor
                                          : context.textMuted.withAlpha(100),
                                      width: _selectedIndices.contains(index + 1) ? 2.5 : 2,
                                    ),
                                  ),
                                  child: Center(
                                    child: Text(
                                      letter,
                                      style: GoogleFonts.outfit(
                                        fontSize: context.scale(18),
                                        fontWeight: FontWeight.w800,
                                        color: context.textPrimary,
                                      ),
                                    ),
                                  ),
                                ),
                              ),
                            );
                          }),
                          ],
                        ),
                      ),
                    ),
                  ),
                ),
                ),
              ),
            const SizedBox(height: 16),
              // Action button - backspace only (drag auto-submits, tap guess to submit)
              if (!_won && !_tutorialCompleted)
                Center(
                  child: IconButton(
                    tooltip: 'Backspace',
                    icon: Icon(Icons.backspace_outlined, size: context.scale(22)),
                    onPressed: _backspace,
                    color: context.textSecondary,
                  ),
                ),
              if (_won && !_isTutorialMode) ...[
                const SizedBox(height: 12),
                Center(
                  child: AutoNextCountdown(
                    onNext: _nextLevel,
                    accentColor: accentColor,
                  ),
                ),
              ],
              const SizedBox(height: 12),
            ],
          ),
        ),
      ),
      if (_won && _playDailyMode)
        Positioned.fill(
          child: ChallengeClearedOverlay(
            accentColor: accentColor,
            onComplete: () {
              Navigator.pop(context, true);
            },
          ),
        ),
      if (_gameOver)
        Positioned.fill(
          child: LossOverlay(
            onTryAgain: () {
              setState(() {
                _gameOver = false;
                _loadLevel();
              });
            },
            subtitle: 'You ran out of time!',
            accentColor: accentColor,
          ),
        ),
      // if (_isTutorialMode)
      //   InteractiveTutorialOverlay(
      //     instruction: _tutorialCompleted
      //         ? "Nice! You successfully found all required words."
      //         : "Swipe and connect letters to form words. Every word must contain the center letter at least once, and be at least 4 letters long!",
      //     isCompleted: _tutorialCompleted,
      //     onSkip: _finishTutorial,
      //     onStartGame: _finishTutorial,
      //   ),
      ],
    ),
    );
  }
}

class _LineConnectorPainter extends CustomPainter {
  final List<Offset> points;
  final ValueNotifier<Offset?> currentDragNotifier;
  final Color color;
  _LineConnectorPainter({required this.points, required this.currentDragNotifier, required this.color})
      : super(repaint: currentDragNotifier);

  @override
  void paint(Canvas canvas, Size size) {
    if (points.isEmpty) return;
    final paint = Paint()
      ..color = color.withOpacity(0.4)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 8.0
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round;

    final path = Path()..moveTo(points[0].dx, points[0].dy);
    for (int i = 1; i < points.length; i++) {
      path.lineTo(points[i].dx, points[i].dy);
    }
    final currentDrag = currentDragNotifier.value;
    if (currentDrag != null) {
      path.lineTo(currentDrag.dx, currentDrag.dy);
    }
    canvas.drawPath(path, paint);
  }

  @override
  bool shouldRepaint(_LineConnectorPainter oldDelegate) {
    return oldDelegate.points.length != points.length ||
           oldDelegate.color != color;
  }
}

class SpotlightFogPainter extends CustomPainter {
  final Color fogColor;
  final double spotlightRadius;

  SpotlightFogPainter({
    required this.fogColor,
    required this.spotlightRadius,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = fogColor
      ..style = PaintingStyle.fill;

    canvas.saveLayer(Offset.zero & size, Paint());
    canvas.drawRect(Offset.zero & size, paint);

    final clearPaint = Paint()
      ..blendMode = BlendMode.clear
      ..style = PaintingStyle.fill;
    canvas.drawCircle(Offset(size.width / 2, size.height / 2), spotlightRadius, clearPaint);
    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant SpotlightFogPainter oldDelegate) {
    return oldDelegate.fogColor != fogColor || oldDelegate.spotlightRadius != spotlightRadius;
  }
}
